function closePopup(){$("#communePopup").hide()}function showPopup(n){var t=$("#communeList");t.empty();$.each(n,function(n,i){var r=$("<div>").addClass("commune-item").text(i.nomCommune+" ("+i.codePostal+")").on("click",function(){$("#CommuneInput").val(i.nomCommune);$("#CodePostal").val(i.codePostal);closePopup()});t.append(r)});$("#communePopup").show()}$(document).ready(function(){$("#CodePostal").on("input",function(){var n=$(this).val();n.length>=4&&n.length<=5&&($("#loader").show(),$.ajax({url:getCommunesUrl,type:"POST",data:{codePostal:n},success:function(n){n.length===1?($("#CommuneInput").val(n[0].nomCommune),$("#CodePostal").val(n[0].codePostal)):n.length>1&&showPopup(n)},error:function(){console.error("Erreur lors de la récupération des communes.")},complete:function(){$("#loader").hide()}}))})});